INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427250, 16222, 'The Guardian', 'en', 'Tropical Storm Dolly downgraded to ‘open tropical wave’ as it heads to Caribbean', 'https://www.theguardian.com/weather/2026/aug/28/tropical-storm-dolly-caribbean', 'Remnants from tropical storm could cause heavy rainfall on Leeward Islands and affect Virgin Islands, Puerto Rico and Hispaniola Remnants of Tropical Storm Dolly, which has been downgraded to an “open tropical wave”, were moving still across the Atlantic Ocean toward the Leeward Islands, and could bring heavy rainfall to parts of the Caribbean this weekend, the US National Hurricane Center (NHC) said on Friday.. Dolly, which formed on Thursday, had maximum sustained winds of near 40mph (65km/h) with higher gusts on Friday morning. Later on Friday, forecasters said that Dolly was no longer a Tr', 'https://i.guim.co.uk/img/media/a351ae3cb184c7f81762912a2e9bce58c9b21f95/167_0_1666_1333/master/1666.jpg?width=140&quality=85&auto=format&fit=max&s=fade6db40f7633e9e6c1dc6e97a616ba', '2026-08-28T15:23:18+00:00', '2026-08-29T00:03:19.487285'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
